import { useId, useRef, useState } from 'react';
import { JxAlert, JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLE_OPTIONS = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'Только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'Правит содержимое' },
  { value: 'admin', label: 'Администратор', meta: 'Полный доступ' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('editor');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const formId = useId();
  const submitRef = useRef<HTMLButtonElement>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const errorText = touched && !isValid ? 'Нужен адрес вида name@company.com' : undefined;

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  };

  const dismiss = () => {
    setInvited(null);
    submitRef.current?.focus();
  };

  return (
    <div style={{ display: 'grid', gap: 16, maxWidth: 420 }}>
      {invited ? (
        <JxAlert intent="success" title="Приглашение отправлено" role="status">
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
            <span style={{ flex: 1, minWidth: 0, overflowWrap: 'anywhere' }}>
              {invited} получит доступ, как только примет приглашение.
              {notify ? ' Уведомление на почту отправлено.' : ' Уведомление на почту не отправлялось.'}
            </span>
            <JxButton variant="ghost" size="sm" iconOnly aria-label="Закрыть сообщение" onClick={dismiss}>
              ✕
            </JxButton>
          </div>
        </JxAlert>
      ) : null}

      <form id={formId} onSubmit={submit} noValidate style={{ display: 'grid', gap: 16 }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          name="email"
          required
          autoComplete="email"
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Приглашение придёт на этот адрес и будет действовать 7 дней"
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={(value) => setRole(value as Role)}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: 8 }}>
          <JxButton ref={submitRef} type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

